/*
 * test_mlkem.c - test suite for the C ML-KEM implementation.
 *
 *   1. SHA-3 / SHAKE known answers (incl. multi-block squeeze)
 *   2. NTT / inverse NTT round trip
 *   3. KATs generated by the independent Python implementation (kyber-py)
 *   4. Randomized round trips (keygen -> encaps -> decaps)
 *   5. Implicit rejection (FO transform): tampered ct -> J(z, c), deterministic
 *   6. Input validation (bad ek modulus, bad dk hash)
 *
 * Run from the repository root:  ./test_mlkem   (KAT files in tests/kat/)
 */
#include "fips202.h"
#include "mlkem.h"
#include "mlkem_internal.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int failures = 0, checks = 0;
#define CHECK(cond, ...)                                                      \
    do {                                                                      \
        checks++;                                                             \
        if (!(cond)) {                                                        \
            failures++;                                                       \
            printf("  FAIL %s:%d: ", __FILE__, __LINE__);                     \
            printf(__VA_ARGS__);                                              \
            printf("\n");                                                     \
        }                                                                     \
    } while (0)

static void tohex(char *out, const uint8_t *in, size_t n)
{
    static const char *d = "0123456789abcdef";
    for (size_t i = 0; i < n; i++) {
        out[2 * i] = d[in[i] >> 4];
        out[2 * i + 1] = d[in[i] & 15];
    }
    out[2 * n] = 0;
}

static int unhex(uint8_t *out, const char *s, size_t n)
{
    for (size_t i = 0; i < n; i++) {
        unsigned v;
        if (sscanf(s + 2 * i, "%2x", &v) != 1)
            return -1;
        out[i] = (uint8_t)v;
    }
    return 0;
}

/* ---------------------------------------------------------------------- */
static void test_sha3(void)
{
    printf("[1] SHA-3 / SHAKE known answers\n");
    uint8_t o[64], big[300];
    char hex[700];

    sha3_256(o, (const uint8_t *)"", 0);
    tohex(hex, o, 32);
    CHECK(!strcmp(hex, "a7ffc6f8bf1ed76651c14756a061d662f580ff4de43b49fa82d80a4b80f8434a"), "sha3-256('')");

    sha3_256(o, (const uint8_t *)"abc", 3);
    tohex(hex, o, 32);
    CHECK(!strcmp(hex, "3a985da74fe225b2045c172d6bd390bd855f086e3e9d525b46bfe24511431532"), "sha3-256(abc)");

    sha3_512(o, (const uint8_t *)"abc", 3);
    tohex(hex, o, 64);
    CHECK(!strcmp(hex, "b751850b1a57168a5693cd924b6b096e08f621827444f70d884f5d0240d2712e"
                       "10e116e9192af3c91a7ec57647e3934057340b4cf408d5a56592f8274eec53f0"), "sha3-512(abc)");

    shake128(o, 32, (const uint8_t *)"", 0);
    tohex(hex, o, 32);
    CHECK(!strcmp(hex, "7f9c2ba4e88f827d616045507605853ed73b8093f6efbc88eb1a6eacfa66ef26"), "shake128('')");

    shake256(o, 32, (const uint8_t *)"", 0);
    tohex(hex, o, 32);
    CHECK(!strcmp(hex, "46b9dd2b0ba88d13233b3feb743eeb243fcd52ea62b81b82b50c27646ed5762f"), "shake256('')");

    /* multi-block absorb (300 B) and multi-block squeeze (300 B), hashed down */
    uint8_t in[300];
    for (int i = 0; i < 100; i++)
        memcpy(in + 3 * i, "abc", 3);
    shake128(big, sizeof big, in, sizeof in);
    sha3_256(o, big, sizeof big);
    tohex(hex, o, 32);
    CHECK(!strcmp(hex, "01bc73488f97db5f102cbc28be0888c078d611f9d3215f0c3f55911023695606"), "shake128 multi-block");
    shake256(big, sizeof big, in, sizeof in);
    sha3_256(o, big, sizeof big);
    tohex(hex, o, 32);
    CHECK(!strcmp(hex, "0f36214b0b5965fc2cfaefb6b6e8f7379360727a56f950da9786b2df8da66a24"), "shake256 multi-block");

    /* incremental squeeze == one-shot */
    uint8_t a[400], b[400];
    shake128(a, sizeof a, in, 77);
    keccak_ctx c;
    keccak_init(&c, SHAKE128_RATE, 0x1f);
    keccak_absorb(&c, in, 33);
    keccak_absorb(&c, in + 33, 44);
    keccak_finalize(&c);
    size_t off = 0, step[] = {1, 7, 8, 160, 3, 221};
    for (int i = 0; i < 6; i++) {
        keccak_squeeze(&c, b + off, step[i]);
        off += step[i];
    }
    CHECK(memcmp(a, b, off) == 0, "incremental absorb/squeeze consistency");
}

/* ---------------------------------------------------------------------- */
static void test_ntt(void)
{
    printf("[2] NTT round trip\n");
    uint16_t f[256], g[256];
    uint32_t x = 12345;
    for (int trial = 0; trial < 200; trial++) {
        for (int i = 0; i < 256; i++) {
            x = x * 1664525u + 1013904223u;
            f[i] = (uint16_t)((x >> 8) % MLKEM_Q);
        }
        memcpy(g, f, sizeof f);
        mlkem_ntt(g);
        for (int i = 0; i < 256; i++)
            if (g[i] >= MLKEM_Q) { CHECK(0, "ntt output not reduced"); break; }
        mlkem_invntt(g);
        CHECK(memcmp(f, g, sizeof f) == 0, "invntt(ntt(f)) == f (trial %d)", trial);
        if (memcmp(f, g, sizeof f)) break;
    }
}

/* ---------------------------------------------------------------------- */
static void test_kat(const mlkem_params *p, const char *file)
{
    printf("[3] KAT vs. kyber-py: %s\n", p->name);
    FILE *fp = fopen(file, "r");
    if (!fp) {
        printf("  FAIL cannot open %s (run from the repo root)\n", file);
        failures++;
        return;
    }
    static char line[1024];
    int n = 0;
    while (fgets(line, sizeof line, fp)) {
        char seedh[129], mh[65], hek[65], hdk[65], hct[65], kh[65];
        if (sscanf(line, "%128s %64s %64s %64s %64s %64s", seedh, mh, hek, hdk, hct, kh) != 6)
            continue;
        uint8_t seed[64], m[32], ek[MLKEM_MAX_EK_BYTES], dk[MLKEM_MAX_DK_BYTES],
            ct[MLKEM_MAX_CT_BYTES], ss[32], ss2[32], h[32];
        char hex[65];
        unhex(seed, seedh, 64);
        unhex(m, mh, 32);

        mlkem_keygen_derand(p, ek, dk, seed);
        sha3_256(h, ek, p->ek_bytes);  tohex(hex, h, 32);
        CHECK(!strcmp(hex, hek), "%s KAT %d: ek hash", p->name, n);
        sha3_256(h, dk, p->dk_bytes);  tohex(hex, h, 32);
        CHECK(!strcmp(hex, hdk), "%s KAT %d: dk hash", p->name, n);

        CHECK(mlkem_encaps_derand(p, ct, ss, ek, m) == 0, "encaps rc");
        sha3_256(h, ct, p->ct_bytes);  tohex(hex, h, 32);
        CHECK(!strcmp(hex, hct), "%s KAT %d: ct hash", p->name, n);
        tohex(hex, ss, 32);
        CHECK(!strcmp(hex, kh), "%s KAT %d: shared secret (encaps)", p->name, n);

        CHECK(mlkem_decaps(p, ss2, ct, dk) == 0, "decaps rc");
        CHECK(memcmp(ss, ss2, 32) == 0, "%s KAT %d: decaps == encaps", p->name, n);
        n++;
    }
    fclose(fp);
    CHECK(n > 0, "no KAT lines read");
    printf("  %d vectors\n", n);
}

/* ---------------------------------------------------------------------- */
static void test_roundtrip(const mlkem_params *p, int iters)
{
    printf("[4] Round trips: %s (%d)\n", p->name, iters);
    uint8_t ek[MLKEM_MAX_EK_BYTES], dk[MLKEM_MAX_DK_BYTES], ct[MLKEM_MAX_CT_BYTES];
    uint8_t s1[32], s2[32];
    int ok = 1;
    for (int i = 0; i < iters && ok; i++) {
        if (mlkem_keygen(p, ek, dk) || mlkem_encaps(p, ct, s1, ek) ||
            mlkem_decaps(p, s2, ct, dk) || memcmp(s1, s2, 32)) {
            ok = 0;
            CHECK(0, "%s round trip failed at iteration %d", p->name, i);
        }
    }
    CHECK(ok, "round trips");
}

static void test_implicit_rejection(const mlkem_params *p)
{
    printf("[5] Implicit rejection: %s\n", p->name);
    uint8_t ek[MLKEM_MAX_EK_BYTES], dk[MLKEM_MAX_DK_BYTES], ct[MLKEM_MAX_CT_BYTES],
        bad[MLKEM_MAX_CT_BYTES];
    uint8_t s1[32], s2[32], s3[32], expect[32];
    mlkem_keygen(p, ek, dk);
    mlkem_encaps(p, ct, s1, ek);

    const uint8_t *z = dk + 768 * p->k + 64;
    int distinct = 1;
    /* flip one bit in every region of the ciphertext: u part, v part, last byte */
    size_t pos[] = {0, p->ct_bytes / 2, p->ct_bytes - 1, 32 * p->du * p->k};
    for (size_t t = 0; t < sizeof pos / sizeof pos[0]; t++) {
        memcpy(bad, ct, p->ct_bytes);
        bad[pos[t]] ^= 0x01;
        CHECK(mlkem_decaps(p, s2, bad, dk) == 0, "decaps(bad) must not error");
        CHECK(mlkem_decaps(p, s3, bad, dk) == 0, "decaps(bad) again");
        CHECK(memcmp(s2, s3, 32) == 0, "rejection key is deterministic");
        CHECK(memcmp(s2, s1, 32) != 0, "tampered ct must not give the real key");
        /* must equal J(z || c) = SHAKE256(z || c, 32) */
        uint8_t in[32 + MLKEM_MAX_CT_BYTES];
        memcpy(in, z, 32);
        memcpy(in + 32, bad, p->ct_bytes);
        shake256(expect, 32, in, 32 + p->ct_bytes);
        CHECK(memcmp(s2, expect, 32) == 0, "rejection key == SHAKE256(z||c)");
        distinct &= memcmp(s2, s1, 32) != 0;
    }
    CHECK(distinct, "distinct");
}

static void test_input_checks(const mlkem_params *p)
{
    printf("[6] Input validation: %s\n", p->name);
    uint8_t ek[MLKEM_MAX_EK_BYTES], dk[MLKEM_MAX_DK_BYTES], ct[MLKEM_MAX_CT_BYTES], ss[32];
    mlkem_keygen(p, ek, dk);

    /* make the first 12-bit coefficient of ek equal 0xFFF (>= q): not canonical */
    uint8_t bad_ek[MLKEM_MAX_EK_BYTES];
    memcpy(bad_ek, ek, p->ek_bytes);
    bad_ek[0] = 0xFF;
    bad_ek[1] |= 0x0F;
    CHECK(mlkem_encaps(p, ct, ss, bad_ek) == -1, "encaps must reject non-canonical ek");

#ifndef MLKEM_SKIP_DK_CHECK
    uint8_t bad_dk[MLKEM_MAX_DK_BYTES];
    memcpy(bad_dk, dk, p->dk_bytes);
    bad_dk[768 * p->k + 5] ^= 0x80; /* corrupt embedded ek -> H(ek) mismatch */
    mlkem_encaps(p, ct, ss, ek);
    CHECK(mlkem_decaps(p, ss, ct, bad_dk) == -1, "decaps must reject inconsistent dk");
#endif
}

int main(void)
{
    const mlkem_params *sets[] = {&mlkem512, &mlkem768, &mlkem1024};
    const char *kat[] = {"tests/kat/mlkem512.kat", "tests/kat/mlkem768.kat", "tests/kat/mlkem1024.kat"};

    printf("ML-KEM (Kyber) C implementation - test suite\n\n");
    test_sha3();
    test_ntt();
    for (int i = 0; i < 3; i++) {
        const mlkem_params *p = sets[i];
        /* size sanity vs. FIPS 203 Table 3 */
        CHECK(p->ek_bytes == 384u * p->k + 32, "ek size formula");
        CHECK(p->dk_bytes == 768u * p->k + 96, "dk size formula");
        CHECK(p->ct_bytes == 32u * (p->du * p->k + p->dv), "ct size formula");
        test_kat(p, kat[i]);
        test_roundtrip(p, 500);
        test_implicit_rejection(p);
        test_input_checks(p);
    }
    printf("\n%d checks, %d failed\n", checks, failures);
    printf(failures ? "RESULT: FAIL\n" : "RESULT: PASS\n");
    return failures ? 1 : 0;
}

